problems.solutionCode:
function createQuotaTracker(initialRemaining, maxQuota = 100) {
  if (!Number.isInteger(maxQuota) || maxQuota < 0) {
    throw new RangeError('maxQuota must be a non-negative integer');
  }
  let remaining = initialRemaining ?? maxQuota;
  if (!Number.isInteger(remaining) || remaining < 0 || remaining > maxQuota) {
    throw new RangeError('initialRemaining must be an integer between 0 and maxQuota');
  }
  return {
    consume(cost = 1) {
      if (!Number.isInteger(cost) || cost <= 0) {
        throw new RangeError('cost must be a positive integer');
      }
      if (remaining < cost) {
        return false;
      }
      remaining -= cost;
      return true;
    },
    refill(amount) {
      if (!Number.isInteger(amount) || amount < 0) {
        throw new RangeError('amount must be a non-negative integer');
      }
      remaining = Math.min(maxQuota, remaining + amount);
      return remaining;
    },
    getRemaining() {
      return remaining;
    },
  };
}

module.exports = { createQuotaTracker };

