function createIdempotencyStore(_maxEntries = 50) {
  // TODO: implement bounded idempotency store with defensive copies
  return {
    record() {
      return false;
    },
    get() {
      return null;
    },
    listKeys() {
      return [];
    },
  };
}

module.exports = { createIdempotencyStore };

problems.solutionCode:
function cloneBody(body) {
  if (body !== null && typeof body === 'object') {
    return Array.isArray(body) ? [...body] : { ...body };
  }
  return body;
}

function createIdempotencyStore(maxEntries = 50) {
  if (!Number.isInteger(maxEntries) || maxEntries <= 0) {
    throw new RangeError('maxEntries must be a positive integer');
  }
  const entries = new Map();
  return {
    record(key, statusCode, body) {
      if (typeof key !== 'string' || key.length === 0) {
        throw new TypeError('key must be a non-empty string');
      }
      if (entries.has(key)) {
        return false;
      }
      if (entries.size >= maxEntries) {
        const oldestKey = entries.keys().next().value;
        entries.delete(oldestKey);
      }
      entries.set(key, { key, statusCode, body: cloneBody(body) });
      return true;
    },
    get(key) {
      const entry = entries.get(key);
      if (!entry) {
        return null;
      }
      return { key: entry.key, statusCode: entry.statusCode, body: cloneBody(entry.body) };
    },
    listKeys() {
      return Array.from(entries.keys());
    },
  };
}

module.exports = { createIdempotencyStore };

