    },
  };
}

module.exports = { createIdempotencyStore };

visibleTests.testCode:
const store = createIdempotencyStore(2);
assert.strictEqual(store.record('evt_1', 200, { ok: true }), true);
assert.strictEqual(store.record('evt_1', 500, { ok: false }), false);
assert.strictEqual(store.record('evt_2', 201, { id: 2 }), true);
assert.strictEqual(store.record('evt_3', 202, { id: 3 }), true);
assert.strictEqual(store.get('evt_1'), null);
assert.deepStrictEqual(store.listKeys(), ['evt_2', 'evt_3']);

assert.throws(() => createIdempotencyStore(0), RangeError);
const store = createIdempotencyStore(5);
assert.throws(() => store.record('', 200, {}), TypeError);

