  let idx = 0;
  for (; idx < routes.length; idx += 1) {
    dispatchers[routes[idx].name] = (payload) => ({
      route: routes[idx].name,
      target: routes[idx].target,
      payload,
    });
  }
  return dispatchers;
}

module.exports = { buildRouteDispatchers };

