problems.starterCode:
function createRetryExecutor(policyConfig) {
  const maxRetries = policyConfig.maxRetries;
  const backoffMs = policyConfig.backoffMs;
  return (attemptNumber) => {
    if (attemptNumber > maxRetries) {
      return { shouldRetry: false, delayMs: 0 };
    }
    return {
      shouldRetry: true,
      delayMs: backoffMs * attemptNumber,
    };
  };
}

module.exports = { createRetryExecutor };

